        for (int j = m - 1; j >= 0; j--) {
            // 终点位置无法继续移动
            if (i == n - 1 && j == m - 1) {
                dp[i][j] = 0;
                continue;
            }

            // 当前轮到天才操作，他希望最终差值尽量大
            if ((i + j) % 2 == 0) {
                int best = INT_MIN;

                // 向下走
                if (i + 1 < n) {
